"""Generate fake_responses.json: example dashboard API responses with no headset.

Run from the repository root:

    python3 -m tests.fixtures.dashboard_api.generate_fixture

Every response is produced by the real ``DashboardService`` fed with scripted
EEG_PACKET lines and a fake clock, so the fixture always matches what the
backend sends. Session IDs, clocks and wall-clock times are fixed, so the output
is identical every run.

SYNTHETIC ONLY: the values are generated, not recorded. See README.md here.
"""

from __future__ import annotations

import json
import math
import tempfile
import time
from pathlib import Path

from eeg_app import dashboard_service, recording
from eeg_app.dashboard_service import ApiError, DashboardService
from eeg_app.preprocessing import REQUIRED_CHANNELS
from eeg_app.recording import NOMINAL_SAMPLE_RATE_HZ, PACKET_INDEX_MODULUS, SAMPLES_PER_PACKET

FIXTURE_PATH = Path(__file__).resolve().parent / "fake_responses.json"
SESSION_ID = "ses-k7q2m9xa"
OTHER_SESSION_ID = "ses-lostconn"
FIXED_UTC = "2026-11-04T18:02:11Z"

FIRST_PACKET_INDEX = 65500  # wraps past 65535 during the session
PACKET_SLOTS = 256  # 12 s
MISSING_AF7_SLOT = 200  # one missing AF7 packet at 9.375 s
BLINK_START_S, BLINK_END_S = 10.5, 10.8  # blink-shaped bump on AF7 and AF8
START_NS = 1_000_000_000_000
PACKET_NS = round(SAMPLES_PER_PACKET / NOMINAL_SAMPLE_RATE_HZ * 1e9)


class FakeClock:
    def __init__(self, now_ns: int):
        self.now_ns = now_ns

    def monotonic_ns(self) -> int:
        return self.now_ns


def microvolts(channel: str, t: float) -> float:
    offset = REQUIRED_CHANNELS.index(channel)
    value = 8 * math.sin(2 * math.pi * 10 * t + offset) + 3 * math.sin(2 * math.pi * 0.4 * t)
    if channel in ("AF7", "AF8") and BLINK_START_S <= t < BLINK_END_S:
        value += 150 * math.sin(math.pi * (t - BLINK_START_S) / (BLINK_END_S - BLINK_START_S))
    return round(value, 2)


def packet_lines(slot: int, receipt_ns: int) -> list[str]:
    index = (FIRST_PACKET_INDEX + slot) % PACKET_INDEX_MODULUS
    lines = []
    for channel in REQUIRED_CHANNELS:
        if channel == "AF7" and slot == MISSING_AF7_SLOT:
            continue
        values = (
            microvolts(channel, (slot * SAMPLES_PER_PACKET + position) / NOMINAL_SAMPLE_RATE_HZ)
            for position in range(SAMPLES_PER_PACKET)
        )
        lines.append(f"EEG_PACKET,{channel},{index},{receipt_ns},{','.join(map(str, values))}")
    return lines


def wait_for(condition, timeout_s: float = 10.0) -> None:
    deadline = time.monotonic() + timeout_s
    while not condition():
        if time.monotonic() > deadline:
            raise TimeoutError("recorder thread did not catch up")
        time.sleep(0.005)


def entry(method: str, path: str, status: int, body: dict, request_body: dict | None = None) -> dict:
    request = {"method": method, "path": path}
    if request_body is not None:
        request["body"] = request_body
    return {"request": request, "status": status, "body": body}


def error_entry(method: str, path: str, call, request_body: dict | None = None) -> dict:
    try:
        call()
    except ApiError as error:
        return entry(method, path, error.status, {"error": {"code": error.code, "message": error.message}}, request_body)
    raise AssertionError(f"{method} {path} did not fail")


def build(work_dir: Path) -> dict:
    clock = FakeClock(START_NS - 2_000_000_000)
    original_time = dashboard_service.time
    original_utc = (dashboard_service._utc_now, recording._utc_now)
    session_ids = iter([SESSION_ID, OTHER_SESSION_ID])
    original_new_id = DashboardService._new_session_id
    dashboard_service.time = clock
    dashboard_service._utc_now = recording._utc_now = lambda: FIXED_UTC
    DashboardService._new_session_id = lambda self: next(session_ids)
    try:
        return _build(work_dir, clock)
    finally:
        dashboard_service.time = original_time
        dashboard_service._utc_now, recording._utc_now = original_utc
        DashboardService._new_session_id = original_new_id


def _build(work_dir: Path, clock: FakeClock) -> dict:
    fixture: dict = {
        "_about": (
            "SYNTHETIC example responses for docs/dashboard-api.md, generated by "
            "tests/fixtures/dashboard_api/generate_fixture.py from the real backend code. "
            "No headset was used. Each entry is {request, status, body}."
        ),
        "status": {},
        "errors": {},
    }
    sessions = work_dir / "sessions"
    service = DashboardService(sessions, work_dir / "review", data_source="fake_headset")

    service.on_scanner_missing("muse2-c/build/muse2_scan not found. Build it with: cd muse2-c && make scan")
    fixture["status"]["scanner_missing"] = entry("GET", "/api/status", 200, service.status())
    service.on_scanner_started()
    fixture["status"]["searching"] = entry("GET", "/api/status", 200, service.status())
    fixture["pilot_sequence"] = entry("GET", "/api/pilot-sequence", 200, service.pilot_sequence())

    # Packets arrive before the session starts (headset on, operator in setup).
    for line in packet_lines(0, clock.now_ns):
        service.on_scanner_line(line)
    clock.now_ns += 30_000_000
    fixture["status"]["idle_streaming"] = entry("GET", "/api/status", 200, service.status())

    clock.now_ns = START_NS
    start_body = {"protocol_id": "eeg-artifact-observation-v1", "participant_code": "P001", "visit_number": 1}
    fixture["start_session"] = entry("POST", "/api/sessions", 201, service.start_session(start_body), start_body)
    fixture["status"]["waiting_for_packets"] = entry("GET", "/api/status", 200, service.status())
    fixture["errors"]["session_already_active"] = error_entry(
        "POST", "/api/sessions", lambda: service.start_session({}), {}
    )
    base = f"/api/sessions/{SESSION_ID}"

    def feed(slots: range) -> None:
        for slot in slots:
            clock.now_ns = START_NS + 250_000_000 + slot * PACKET_NS
            for line in packet_lines(slot, clock.now_ns):
                service.on_scanner_line(line)
        expected = sum(len(packet_lines(slot, 0)) for slot in range(slots.stop)) * SAMPLES_PER_PACKET
        wait_for(lambda: service._active.rows_written == expected)

    def post_event(body: dict) -> dict:
        status, event = service.add_event(SESSION_ID, body)
        return entry("POST", f"{base}/events", status, event, body)

    def event_body(event_type, label, source, client_ref, event_code=None, corrects_event_id=None):
        return {
            "event_type": event_type, "label": label, "source": source, "event_code": event_code,
            "corrects_event_id": corrects_event_id, "client_ref": client_ref,
        }

    feed(range(0, 4))
    post_event(event_body(
        "contact_quality_unverified", "Contact quality not measured; operator acknowledged warning",
        "operator", "c0a1d6a2-0001-4c55-9a51-6d2e8f0c4b11",
    ))
    post_event(event_body("prompt_shown", "NOW: Rest quietly", "protocol",
                          "c0a1d6a2-0002-4c55-9a51-6d2e8f0c4b11", "PILOT_CUE_0"))
    feed(range(4, 150))
    post_event(event_body("prompt_shown", "Get ready to blink", "protocol",
                          "c0a1d6a2-0003-4c55-9a51-6d2e8f0c4b11", "PILOT_READY_1"))
    feed(range(150, 214))
    post_event(event_body("prompt_shown", "NOW: Blink softly twice, then firmly once", "protocol",
                          "c0a1d6a2-0004-4c55-9a51-6d2e8f0c4b11", "PILOT_CUE_1"))
    fixture["live_first_poll"] = entry("GET", f"{base}/live", 200, service.live(SESSION_ID, None))
    cursor = fixture["live_first_poll"]["body"]["cursor"]
    feed(range(214, 230))
    blink = event_body("observer_marker", "Observed blink", "operator", "c0a1d6a2-0005-4c55-9a51-6d2e8f0c4b11")
    fixture["add_event"] = post_event(blink)
    fixture["add_event_retry_same_client_ref"] = post_event(blink)
    fixture["live_next_poll"] = entry("GET", f"{base}/live?after={cursor}", 200, service.live(SESSION_ID, cursor))
    jaw = event_body("observer_marker", "Observed jaw / facial muscle", "operator",
                     "c0a1d6a2-0006-4c55-9a51-6d2e8f0c4b11")
    jaw_event = post_event(jaw)["body"]
    correction = event_body(
        "marker_correction", f"Correction: accidental marker — {jaw_event['label']}", "operator",
        "c0a1d6a2-0007-4c55-9a51-6d2e8f0c4b11", corrects_event_id=jaw_event["event_id"],
    )
    fixture["add_correction"] = post_event(correction)
    feed(range(230, PACKET_SLOTS))
    fixture["status"]["recording"] = entry("GET", "/api/status", 200, service.status())

    bad = event_body("observer_marker", "Observed blink", "operator", "c0a1d6a2-0099-4c55-9a51-6d2e8f0c4b11")
    fixture["errors"]["invalid_request"] = error_entry(
        "POST", f"{base}/events", lambda: service.add_event(SESSION_ID, {**bad, "event_type": "blink"}),
        {**bad, "event_type": "blink"},
    )
    fixture["errors"]["unknown_event_reference"] = error_entry(
        "POST", f"{base}/events",
        lambda: service.add_event(SESSION_ID, {**correction, "corrects_event_id": "evt-9999", "client_ref": "x"}),
        {**correction, "corrects_event_id": "evt-9999", "client_ref": "x"},
    )
    fixture["errors"]["session_still_recording"] = error_entry(
        "GET", base, lambda: service.summary(SESSION_ID)
    )

    clock.now_ns += 400_000_000
    end_body = {"outcome": "incomplete", "reason": "Participant asked to stop after the blink prompt."}
    fixture["end_session"] = entry("POST", f"{base}/end", 200, service.end_session(SESSION_ID, end_body), end_body)
    fixture["errors"]["session_not_recording"] = error_entry(
        "POST", f"{base}/events", lambda: service.add_event(SESSION_ID, {**bad, "client_ref": "y"}),
        {**bad, "client_ref": "y"},
    )
    fixture["errors"]["session_not_found"] = error_entry(
        "GET", "/api/sessions/ses-nosuchid", lambda: service.summary("ses-nosuchid")
    )

    fixture["list_sessions"] = entry("GET", "/api/sessions", 200, service.list_sessions())
    fixture["session_summary"] = entry("GET", base, 200, service.summary(SESSION_ID))
    fixture["session_events"] = entry("GET", f"{base}/events", 200, service.events(SESSION_ID))
    path = f"{base}/traces?start_s=0&end_s=12&max_points=768"
    fixture["session_traces"] = entry("GET", path, 200, service.traces(SESSION_ID, 0, 12, 768))

    # A second session whose scanner is lost part way through.
    clock.now_ns += 5_000_000_000
    for line in packet_lines(0, clock.now_ns):
        service.on_scanner_line(line)
    service.start_session({})
    wait_for(lambda: service._active.opened.is_set())
    for line in packet_lines(1, clock.now_ns):
        service.on_scanner_line(line)
    service.on_scanner_stopped("Scanner exited with code 1.")
    wait_for(lambda: service._active.state == "interrupted")
    fixture["status"]["interrupted"] = entry("GET", "/api/status", 200, service.status())
    fixture["errors"]["cannot_complete_interrupted"] = error_entry(
        "POST", f"/api/sessions/{OTHER_SESSION_ID}/end",
        lambda: service.end_session(OTHER_SESSION_ID, {"outcome": "completed"}), {"outcome": "completed"},
    )
    service.end_session(OTHER_SESSION_ID, {"outcome": "aborted", "reason": "Lost connection test."})
    fixture["errors"]["scanner_unavailable"] = error_entry(
        "POST", "/api/sessions", lambda: service.start_session({}), {}
    )

    # Messages that name saved files contain the temporary directory; strip it.
    text = json.dumps(fixture, indent=2, ensure_ascii=False).replace(str(work_dir) + "/", "")
    return json.loads(text)


def main() -> None:
    with tempfile.TemporaryDirectory() as tmp:
        fixture = build(Path(tmp))
    FIXTURE_PATH.write_text(json.dumps(fixture, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    print(f"Wrote {FIXTURE_PATH}")


if __name__ == "__main__":
    main()
